CREATE TABLE "PrivateMessage" ("id" TEXT NOT NULL, "requestId" TEXT NOT NULL, "senderId" TEXT NOT NULL, "clientId" TEXT NOT NULL, "body" TEXT NOT NULL CHECK (char_length("body") BETWEEN 1 AND 4000), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "PrivateMessage_pkey" PRIMARY KEY ("id"), CONSTRAINT "PrivateMessage_requestId_fkey" FOREIGN KEY ("requestId") REFERENCES "ConnectionRequest"("id") ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT "PrivateMessage_senderId_fkey" FOREIGN KEY ("senderId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE UNIQUE INDEX "PrivateMessage_requestId_senderId_clientId_key" ON "PrivateMessage"("requestId", "senderId", "clientId");
CREATE INDEX "PrivateMessage_requestId_createdAt_id_idx" ON "PrivateMessage"("requestId", "createdAt", "id");
CREATE TABLE "ConversationState" ("requestId" TEXT NOT NULL, "userId" TEXT NOT NULL, "lastReadAt" TIMESTAMP(3), "blockedAt" TIMESTAMP(3), CONSTRAINT "ConversationState_pkey" PRIMARY KEY ("requestId", "userId"), CONSTRAINT "ConversationState_requestId_fkey" FOREIGN KEY ("requestId") REFERENCES "ConnectionRequest"("id") ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT "ConversationState_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE);

